mapper.select:
SELECT id, model, provider, tenant_scope FROM model_config WHERE enabled = 1 AND version = '1.0.0' AND ( tenant_scope = '*'
OR tenant_scope = #{tenantId}
) ORDER BY
CASE WHEN tenant_scope = #{tenantId} THEN 0 ELSE 1 END,
id DESC LIMIT 1

SELECT id, config_id, model, provider, version, tenant_scope, enabled
FROM model_config
WHERE config_id = #{configId}
  AND version = #{version}
LIMIT 1

mapper.update:
UPDATE model_config
SET enabled = 0
WHERE config_id = #{configId}
  AND version = #{version}
  AND enabled = 1

UPDATE model_config
SET enabled = 1
WHERE config_id = #{configId}
  AND version = #{version}
  AND enabled = 0
